    function _tryParseChr(bytes1 chr) private pure returns (uint8) {
        uint8 value = uint8(chr);

        // Try to parse `chr`:
        // - Case 1: [0-9]
        // - Case 2: [a-f]
        // - Case 3: [A-F]
        // - otherwise not supported
        unchecked {
            if (value > 47 && value < 58) value -= 48;
            else if (value > 96 && value < 103) value -= 87;
            else if (value > 64 && value < 71) value -= 55;
            else return type(uint8).max;
        }

        return value;
    }

    /**
     * @dev Escape special characters in JSON strings. This can be useful to prevent JSON injection in NFT metadata.
     *
     * WARNING: This function should only be used in double quoted JSON strings. Single quotes are not escaped.
     *
     * NOTE: This function escapes backslashes (including those in \uXXXX sequences) and the characters in ranges
     * defined in section 2.5 of RFC-4627 (U+0000 to U+001F, U+0022 and U+005C). All control characters in U+0000
     * to U+001F are escaped (\b, \t, \n, \f, \r use short form; others use \u00XX). ECMAScript's `JSON.parse` does
     * recover escaped unicode characters that are not in this range, but other tooling may provide different results.
     */
    function escapeJSON(string memory input) internal pure returns (string memory) {
        bytes memory buffer = bytes(input);

        // Put output at the FMP. Memory will be reserved later when we figure out the actual length of the escaped
        // string. All write are done using _unsafeWriteBytesOffset, which avoid the (expensive) length checks for
        // each character written.
        bytes memory output;
        assembly ("memory-safe") {
            output := mload(0x40)
        }
        uint256 outputLength = 0;

        for (uint256 i = 0; i < buffer.length; ++i) {
            uint8 char = uint8(bytes1(_unsafeReadBytesOffset(buffer, i)));
            if (((SPECIAL_CHARS_LOOKUP & (1 << char)) != 0)) {
                _unsafeWriteBytesOffset(output, outputLength++, "\\");
                if (char == 0x08) _unsafeWriteBytesOffset(output, outputLength++, "b");
                else if (char == 0x09) _unsafeWriteBytesOffset(output, outputLength++, "t");
                else if (char == 0x0a) _unsafeWriteBytesOffset(output, outputLength++, "n");
                else if (char == 0x0c) _unsafeWriteBytesOffset(output, outputLength++, "f");
                else if (char == 0x0d) _unsafeWriteBytesOffset(output, outputLength++, "r");
                else if (char == 0x5c) _unsafeWriteBytesOffset(output, outputLength++, "\\");
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    _unsafeWriteBytesOffset(output, outputLength++, '"');
                } else {
                    // U+0000 to U+001F without short form: output \u00XX
                    _unsafeWriteBytesOffset(output, outputLength++, "u");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char >> 4]);
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char & 0x0f]);
                }
            } else {
                _unsafeWriteBytesOffset(output, outputLength++, bytes1(char));
            }
        }
        // write the actual length and reserve memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, add(outputLength, 0x20)))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }

    /**
     * @dev Write a bytes1 to a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeWriteBytesOffset(bytes memory buffer, uint256 offset, bytes1 value) private pure {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

src/AuctionEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// Interface for the Merkaba Treasury
interface IMerkabaCore {
    function injectCapital(uint256 amount) external;
}

// Interface for Genesis Node
interface IGenesisNode {
    function depositSunRewards(uint256 amount) external;
}

/**
 * @title ArcadeAuctionEngine
 * @author AI Arcade Systems (The New Fuse)
 * @notice The "Machine" on the Arcade floor. Handles bids, price drops, and item delivery.
 * @dev Integrates with MerkabaCore for liquidity recycling.
 */
contract AuctionEngine is Ownable, ReentrancyGuard {

    // --- Configuration ---
    IERC20 public arcadeToken;      // The "Quarter" (ERC-20 Token)
    IMerkabaCore public merkabaCore; // The Treasury (The Battery)
    IGenesisNode public genesisNode; // The Equity (The Keys)

    // --- The "Arcade Cabinet" Data ---
    struct Auction {
        uint256 id;
        string agentId;      // e.g., "DeepSeek-R1-Lifetime" or "TNF-Director-001"
        uint256 currentPrice;// The "Buy Now" Price
        uint256 floorPrice;  // The absolute minimum (Reserve)
        uint256 priceDrop;   // How much price drops per BID
        uint256 bidFee;      // Cost to play (insert coin)
        bool active;
        address winner;
        address lastBidder;  // For "Sniper" mechanics
        uint256 endTime;     // Optional: For "Candle" auctions
    }

    uint256 public auctionCount;
    mapping(uint256 => Auction) public auctions;

    // --- RPG Stats (Loss Mining) ---
    // We track "Volume" to sync with the Frontend Leaderboard
    mapping(address => uint256) public userVolume;

    // --- Events (Websocket Hooks) ---
    // The frontend listens to these to update the UI in real-time
    event CabinetCreated(uint256 indexed id, string agentId, uint256 startPrice);
    event CoinInserted(uint256 indexed id, address indexed player, uint256 newPrice, uint256 treasuryInjection);
    event JackpotUnlock(uint256 indexed id, address indexed winner, uint256 finalCost);

    constructor(address _token, address _merkaba, address _genesis) Ownable(msg.sender) {
        arcadeToken = IERC20(_token);
        merkabaCore = IMerkabaCore(_merkaba);
        genesisNode = IGenesisNode(_genesis);
    }

    // --- Admin: Install New Machine ---
    function createCabinet(
        string memory _agentId,
        uint256 _startPrice,
        uint256 _floorPrice,
        uint256 _priceDrop,
        uint256 _bidFee
    ) external onlyOwner {
        auctionCount++;
        auctions[auctionCount] = Auction({
            id: auctionCount,
            agentId: _agentId,
            currentPrice: _startPrice,
            floorPrice: _floorPrice,
            priceDrop: _priceDrop,
            bidFee: _bidFee,
            active: true,
            winner: address(0),
            lastBidder: address(0),
            endTime: block.timestamp + 7 days // Default timeout
        });

        emit CabinetCreated(auctionCount, _agentId, _startPrice);
    }

    // --- Player: Insert Coin (The Bid) ---
    /**
     * @notice The Core Loop. User pays a small fee to drop the price for everyone.
     * @dev Fee is split: Part to Seller (Burn), Part to Merkaba (Treasury).
     */
    function insertCoin(uint256 _auctionId) external nonReentrant {
        Auction storage machine = auctions[_auctionId];
        require(machine.active, "Game Over");
        require(block.timestamp < machine.endTime, "Time expired");
        require(machine.currentPrice > machine.floorPrice, "Floor hit");

        // 1. Take Payment (The Fee)
        require(arcadeToken.transferFrom(msg.sender, address(this), machine.bidFee), "Insert Coin Failed");

        // 2. The Hydraulic Split
        // Fee: $1.00
        // $0.50 -> Revenue (Burn/House - Stays in Contract)
        // $0.40 -> Merkaba (Prizes)
        // $0.10 -> Genesis Nodes (Dividends)

        uint256 fee = machine.bidFee;
        uint256 toGenesis = (fee * 10) / 100; // 10%
        uint256 toTreasury = (fee * 40) / 100; // 40%
        // Remainder (50%) stays in contract

        // Transfer to Genesis
        arcadeToken.approve(address(genesisNode), toGenesis);
        genesisNode.depositSunRewards(toGenesis);

        // Transfer to Treasury
        arcadeToken.approve(address(merkabaCore), toTreasury);
        merkabaCore.injectCapital(toTreasury);

        // 3. Game Logic: Drop the Price
        if (machine.currentPrice >= machine.priceDrop) {
            machine.currentPrice -= machine.priceDrop;
        } else {
            machine.currentPrice = machine.floorPrice;
        }

        // 4. Update Stats (The Sniper)
        machine.lastBidder = msg.sender;
        userVolume[msg.sender] += machine.bidFee; // Add XP for Leaderboard

        emit CoinInserted(_auctionId, msg.sender, machine.currentPrice, toTreasury);
    }

    // --- Player: Buy Now (Win the Prize) ---
    /**
     * @notice User pays the CURRENT discounted price to win the Item.
     * @dev This triggers the Web2 Backend to unlock the Agent.
     */
    function unlockAgent(uint256 _auctionId) external nonReentrant {
        Auction storage machine = auctions[_auctionId];
        require(machine.active, "Game Over");

        // 1. Take Payment (The Price)
        require(arcadeToken.transferFrom(msg.sender, address(this), machine.currentPrice), "Insufficient Funds");

        // 2. Finalize Game
        machine.active = false;
        machine.winner = msg.sender;

        // 3. Loot Distribution
        // Revenue stays here (House) or moves to a Vault.
        // For MVP, we leave it in contract.

        emit JackpotUnlock(_auctionId, msg.sender, machine.currentPrice);
    }
}

src/GenesisNode.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title GenesisNode
 * @author AI Arcade Systems
 * @notice The 8 Cornerstones of the Merkaba.
 * @dev IDs 1-4 (SUN) track Volume. IDs 5-8 (EARTH) track Yield.
 */
contract GenesisNode is ERC721, Ownable, ReentrancyGuard {

    // --- Configuration ---
    IERC20 public paymentToken; // The Arcade Token (USDC/ETH)

    // Limits
    uint256 public constant MAX_SUPPLY = 8;
    uint256 public constant SUN_NODES = 4;
    uint256 public constant EARTH_NODES = 4;

    // --- Dividend Tracking ---
    // We track total rewards *ever* deposited per node type
    uint256 public totalSunRewardsPerNode;   // Total Volume Rewards / 4
    uint256 public totalEarthRewardsPerNode; // Total Yield Rewards / 4

    // We track how much each Token ID has already claimed
    mapping(uint256 => uint256) public claimedAmount;

    // --- Events ---
    event DividendsDeposited(string sourceType, uint256 totalAmount);
    event DividendsClaimed(uint256 indexed tokenId, address indexed owner, uint256 amount);

    constructor(address _paymentToken) ERC721("Merkaba Genesis Node", "MK-GEN") Ownable(msg.sender) {
        paymentToken = IERC20(_paymentToken);
    }

    // --- 1. Minting (The Bootstrap Sale) ---
    /**
     * @notice Mint the 8 Nodes.
     * @dev Initially minted to Admin, then auctioned off via Opensea or custom Dutch Auction.
     */
    function mintGenesis() external onlyOwner {
        // require(totalSupply() == 0, "Already minted"); // totalSupply() isn't standard in base ERC721, using counter logic is better or just loop
         // Using a simple check if ID 1 exists
        require(_ownerOf(1) == address(0), "Already minted");

        for (uint256 i = 1; i <= MAX_SUPPLY; i++) {
            _mint(msg.sender, i);
        }
    }

    // --- 2. The Injection (Money In) ---

    /**
     * @notice Called by AuctionEngine. Adds 1% of Bid Volume to Sun Nodes.
     */
    function depositSunRewards(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Zero value");
        require(paymentToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");

        // Split equally among the 4 Sun Nodes
        uint256 share = _amount / SUN_NODES;
        totalSunRewardsPerNode += share;

        emit DividendsDeposited("SUN_VOLUME", _amount);
    }

    /**
     * @notice Called by MerkabaCore. Adds 1% of Treasury Yield to Earth Nodes.
     */
    function depositEarthRewards(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Zero value");
        require(paymentToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");

        // Split equally among the 4 Earth Nodes
        uint256 share = _amount / EARTH_NODES;
        totalEarthRewardsPerNode += share;

        emit DividendsDeposited("EARTH_YIELD", _amount);
    }

    // --- 3. The Claim (Money Out) ---

    /**
     * @notice Allows NFT holder to pull their accumulated dividends.
     * @dev The dividend stays with the Token ID. If you sell the NFT,
     * the new owner can claim the unclaimed rewards.
     */
    function claimDividends(uint256 _tokenId) external nonReentrant {
        // Updated for newer OpenZeppelin where ownerOf might be different or _ownerOf
        require(ownerOf(_tokenId) == msg.sender, "Not the owner");

        uint256 owed = 0;

        if (_tokenId <= 4) {
            // SUN NODE (1, 2, 3, 4)
            owed = totalSunRewardsPerNode - claimedAmount[_tokenId];
        } else if (_tokenId <= 8) {
            // EARTH NODE (5, 6, 7, 8)
            owed = totalEarthRewardsPerNode - claimedAmount[_tokenId];
        }

        require(owed > 0, "Nothing to claim");

        // Update state BEFORE transfer (Security best practice)
        claimedAmount[_tokenId] += owed;

        // Payout
        require(paymentToken.transfer(msg.sender, owed), "Payout failed");

        emit DividendsClaimed(_tokenId, msg.sender, owed);
    }

    // --- View Functions (For UI) ---

    function getClaimable(uint256 _tokenId) external view returns (uint256) {
        if (_tokenId <= 4) {
             return totalSunRewardsPerNode - claimedAmount[_tokenId];
        } else if (_tokenId <= 8) {
             return totalEarthRewardsPerNode - claimedAmount[_tokenId];
        }
        return 0;
    }
}

src/MerkabaCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MerkabaCore
 * @author AI Arcade Systems
 * @notice The "Gyroscope" that balances Active Liquidity (Sun) vs. Passive Yield (Earth).
 * @dev This contract holds the funds and rebalances them based on the Golden Ratio.
 */
contract MerkabaCore is Ownable, ReentrancyGuard {

    // --- The Sacred Geometry ---
    IERC20 public immutable paymentToken; // The blood of the system (USDC/ETH)

    // The Two Pyramids
    uint256 public sunBalance;   // Active Prize Pools (Hot Liquidity)
    uint256 public earthBalance; // Treasury / Yield Strategies (Cold Storage)

    // The Golden Ratio Config
    uint256 public targetRatio = 100; // 1.00 (1:1 Ratio)
    uint256 public rebalanceStrength = 5; // Move 5% of excess per pulse
    uint256 public constant PRECISION = 100;

    // --- Events (The Heartbeat) ---
    event Deposit(string source, uint256 amount, uint256 splitSun, uint256 splitEarth);
    event Pulse(string action, uint256 amountMoved, uint256 newSun, uint256 newEarth);
    event EmergencyDrain(address target, uint256 amount);

    constructor(address _paymentToken) Ownable(msg.sender) {
        paymentToken = IERC20(_paymentToken);
    }

    // --- 1. The Injection (Money Enters) ---
    /**
     * @notice The Auction Engine sends fees here.
     * @dev Automatically splits the incoming energy based on the Merkaba Logic.
     * Standard Split: 80% Sun (Prizes), 20% Earth (Savings).
     */
    function injectCapital(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Zero energy");

        // Transfer funds from the sender (Auction Engine) to here
        require(paymentToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");

        // The "Default" Split (Can be adjusted via Governance)
        uint256 toSun = (_amount * 80) / 100;
        uint256 toEarth = _amount - toSun;

        sunBalance += toSun;
        earthBalance += toEarth;

        emit Deposit("AuctionFee", _amount, toSun, toEarth);

        // OPTIONAL: Trigger a pulse immediately to check balance
        _pulse();
    }

    // --- 2. The Gyroscope (The Logic) ---
    /**
     * @notice The "Heartbeat" function. Anyone can call it (or a Keeper bot).
     * @dev Checks the ratio between Sun and Earth. Moves funds to restore balance.
     */
    function pulse() external nonReentrant {
        _pulse();
    }

    function _pulse() internal {
        // Safety: Prevent division by zero
        if (earthBalance == 0 || sunBalance == 0) return;

        // Calculate Current Ratio (Sun / Earth)
        // Scaled by 100 for integer math. Example: 120 = 1.2 Ratio
        uint256 currentRatio = (sunBalance * PRECISION) / earthBalance;

        if (currentRatio > targetRatio) {
            // SCENARIO A: SUN IS TOO HOT (Ratio > 1.0)
            // The Arcade is generating too much cash/prizes, but has low backing.
            // ACTION: Siphon excess Heat to Earth (Cooling).

            uint256 excess = sunBalance - earthBalance; // Simplified delta
            uint256 moveAmount = (excess * rebalanceStrength) / 100;

            sunBalance -= moveAmount;
            earthBalance += moveAmount;

            emit Pulse("COOLING: Sun -> Earth", moveAmount, sunBalance, earthBalance);

        } else if (currentRatio < targetRatio) {
            // SCENARIO B: EARTH IS TOO HEAVY (Ratio < 1.0)
            // The Treasury is huge, but the daily prizes are small/boring.
            // ACTION: Pump Gravity into Sun (Heating).

            uint256 shortage = earthBalance - sunBalance; // Simplified delta
            uint256 moveAmount = (shortage * rebalanceStrength) / 100;

            earthBalance -= moveAmount;
            sunBalance += moveAmount;

            emit Pulse("HEATING: Earth -> Sun", moveAmount, sunBalance, earthBalance);
        }
    }

    // --- 3. The Hydraulics (Money Exits) ---
    /**
     * @notice Allows the Auction Engine to pull funds for a Jackpot Winner.
     * @dev Only the "Sun" balance can be touched for prizes.
     */
    function payoutWinner(address _winner, uint256 _amount) external onlyOwner nonReentrant {
        require(_amount <= sunBalance, "Not enough Sun energy");

        sunBalance -= _amount;
        require(paymentToken.transfer(_winner, _amount), "Payout failed");
    }

    /**
     * @notice Allows the Treasury Manager to invest Earth funds into Yield Protocols (Aave/Compound).
     * @dev Funds leave this contract but are tracked as "Earth Balance" via the receipt token.
     */
    function investEarth(address _yieldStrategy, uint256 _amount) external onlyOwner {
        require(_amount <= earthBalance, "Not enough Earth energy");
        // Integration with Aave/Compound would go here
        // For MVP, we just allow the owner to move it to a multisig
        require(paymentToken.transfer(_yieldStrategy, _amount), "Invest failed");
        // Note: We do NOT decrease earthBalance here if we expect the yield strategy
        // to return the funds later. We treat it as "Deployed Capital".
    }
}

